from asset_metadata import attach_generation_metadata
from library_deletion import deleted_keys
purged = deleted_keys(LIB)

records = []
for source, dest, style_family, species, category, title in MAPPINGS:
    if dest in purged:
        continue
    src = ROOT / source
    dst = LIB / dest
    if not src.exists():
        raise FileNotFoundError(src)
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)
    records.append({'path': dest, 'source': source, 'style_family': style_family, 'species': species, 'category': category, 'title': title, 'status': 'confirmed'})

from asset_additions import merge_additions
merge_additions({'assets': records}, LIB)
attach_generation_metadata(records, LIB)
(LIB / 'gallery-manifest.json').write_text(json.dumps({
    'version': '0.5.0',
    'generated_from': 'sync_role_assets.py',
    'asset_count': len(records),
    'policy': 'Only explicit confirmed, locked or current-production authority assets are shown. Candidates and historical/optimising assets are excluded.',
    'assets': records,
}, ensure_ascii=False, indent=2) + '\n')
print(f'synced {len(records)} confirmed role/style assets')
# Rebuild the static browser gallery whenever the confirmed asset list changes.
subprocess.run(['python3', str(LIB / 'build_gallery.py')], check=True, env={**os.environ, 'VICKY_GALLERY_LOCK_PARENT': str(os.getpid())})
